def decode(self,input,errors = 'strict'):
    if isinstance(input, memoryview):
        input = input.tobytes()
    if not isinstance(input,(binary_type,bytearray)):
        raise with_context(exc=TypeError("Can't decode {type}; byte string expected.".format(type=type(input).__name__)), context={'input':input})
    # :bc: In Python 2, iterating over a byte string yields characters instead of integers.
    if not isinstance(input, bytearray):
        input = bytearray(input)
    bytes_ = bytearray()
    for i in range(0,len(input),2):
        try:
            first, second = input[i:i+2]
        except ValueError:
            if errors == 'strict':
                raise with_context(exc=TrytesDecodeError("'{name}' codec can't decode value; tryte sequence has odd length.".format(name=self.name)), context={'input':input})
            elif errors == 'replace':
                bytes_ += b'?'
                continue
        try:
            bytes_.append(self.index[first] + (self.index[second] * len(self.index)))
        except ValueError:
            # This combination of trytes yields a value > 255 when decoded. Naturally, we can't represent this using ASCII.
            if errors == 'strict':
                raise with_context(exc=TrytesDecodeError("'{name}' codec can't decode trytes {pair} at position {i}-{j}: ordinal not in range(255)".format(name=self.name,pair=chr(first)+chr(second),i=i,j=i+1)), context={'input':input})
            elif errors == 'replace':
                bytes_ += b'?'
    return binary_type(bytes_), len(input)


