def _calculate_averages (self):
    for n in self.tree.get_nonterminals (order = 'postorder'):
        Q = np.zeros (6,dtype = float)
        for c in n:
            tv = self.tip_value (c)
            bv = self.branch_value (c)
            var = self.branch_variance (c)
            Q += self.propagate_averages (c,tv,bv,var)
        n.Q = Q
    for n in self.tree.find_clades (order = 'preorder'):
        O = np.zeros (6,dtype = float)
        if n == self.tree.root:
            n.Qtot = n.Q
            continue
        for c in n.up:
            if c == n:
                continue
            tv = self.tip_value (c)
            bv = self.branch_value (c)
            var = self.branch_variance (c)
            O += self.propagate_averages (c,tv,bv,var)
        if n.up != self.tree.root:
            c = n.up
            tv = self.tip_value (c)
            bv = self.branch_value (c)
            var = self.branch_variance (c)
            O += self.propagate_averages (c,tv,bv,var,outgroup = True)
        n.O = O
        if not n.is_terminal ():
            tv = self.tip_value (n)
            bv = self.branch_value (n)
            var = self.branch_variance (n)
            n.Qtot = n.Q + self.propagate_averages (n,tv,bv,var,outgroup = True)

So it calculates averages for nodes. It first processes nonterminals postorder, computing Q for each node by summing propagate_averages over its children. Then it processes clades preorder, computing O for each node by summing propagate_averages over its up neighbors (excluding itself). If node not root, also includes its parent as outgroup. Then sets n.O = O. If node not terminal, compute Qtot as n.Q + propagate_averages for node itself with outgroup True.

